// Class definition — the blueprint
class Student {
    // Fields (instance variables)
    String name;
    int rollNo;
    float marks;

    // Constructor to initialize fields
    Student(String n, int r, float m) {
        name   = n;
        rollNo = r;
        marks  = m;
    }

    // Method to display student details
    void displayInfo() {
        System.out.println("Name   : " + name);
        System.out.println("Roll No: " + rollNo);
        System.out.println("Marks  : " + marks);
        System.out.println("--------");
    }
}

// Main class to run the program
public class Main {
    public static void main(String[] args) {

        // Creating object s1 using new keyword
        Student s1 = new Student("Ravi", 101, 88.5f);

        // Creating object s2 — independent from s1
        Student s2 = new Student("Priya", 102, 92.0f);

        // Accessing method via dot operator
        s1.displayInfo();
        s2.displayInfo();

        // Changing a field of s1 only
        s1.marks = 90.0f;
        System.out.println("Updated marks of s1: " + s1.marks);
        System.out.println("Marks of s2 unchanged: " + s2.marks);
    }
}

